/**
 * Terrain data types. The terrain itself is generated by the Kotlin simulation
 * (compiled to WebAssembly, see src/sim/kotlinSim.ts); these types only describe
 * the shape of the data Kotlin hands over. Nothing here generates or defines terrain.
 *   TileType.kt  -> TileTypeInfo (name, walkable, symbol), sent in `tileTypes`
 *   Terrain.kt   -> TerrainData (width, height, row-major tiles)
 */

/** One entry of Kotlin's `TileType` enum, as reported by the Kotlin side. */
export interface TileTypeInfo {
    /** Kotlin enum name, e.g. "WATER", "PLAIN", "FOREST", "DESERT". */
    readonly name: string;
    readonly walkable: boolean;
    readonly symbol: string;
}

export interface TerrainData {
    readonly width: number;
    readonly height: number;
    /** Kotlin's TileType enum entries, indexed by ordinal. */
    readonly tileTypes: readonly TileTypeInfo[];
    /** Row-major: index = y * width + x. Each value indexes `tileTypes`. */
    readonly tiles: Uint8Array;
}

/** Tile type info at (x, y), mirroring Kotlin `Terrain.at`. */
export function tileAt(t: TerrainData, x: number, y: number): TileTypeInfo {
    return t.tileTypes[t.tiles[y * t.width + x]!]!;
}
